## solution

#### dynamic programming with memoization

```cpp
#include <string>
#include <algorithm>
#include <unordered_map>

int overlapSubsequence(std::string s1, std::string s2, int i, int j, std::unordered_map<std::string, int> &memo) {
  std::string key = std::to_string(i) + "," + std::to_string(j);

  if (memo.count(key) > 0) {
    return memo[key];
  }

  if (i == s1.length() || j == s2.length()) {
    return 0;
  }

  if (s1[i] == s2[j]) {
    memo[key] = 1 + overlapSubsequence(s1, s2, i + 1, j + 1, memo);
  } else {
    memo[key] = std::max(overlapSubsequence(s1, s2, i + 1, j, memo), overlapSubsequence(s1, s2, i, j + 1, memo));
  }
  return memo[key];
}

int overlapSubsequence(std::string s1, std::string s2) {
  std::unordered_map<std::string, int> memo;
  return overlapSubsequence(s1, s2, 0, 0, memo);
}
```

- n = length of str1
- m = length of str2
- Time: O(nm)
- Space: O(nm)
